 {kind:"chart",id:"c-volcano",chartType:"volcano",title:"Treatment versus control: log2 fold change against adjusted p-value",caption:"Genes in the differential expression results table. Dashed lines mark the 0.05 FDR cut and a two-fold change.",binding:{kind:"artifact-table",path:S,columns:["symbol","log2FoldChange","padj"],columnMeanings:{symbol:"identifier",log2FoldChange:"effect",padj:"p-value"},columnLabels:{symbol:"Gene",log2FoldChange:"log2 fold change",padj:"Adjusted p-value"}},encoding:{x:"log2FoldChange",p:"padj",label:"symbol"},thresholds:{significance:0.05,effect:1}}
]}}));
