 {kind:"table",id:"tb-isg",title:"Named interferon-stimulated genes in the results",caption:"Rank is by absolute log2 fold change among all genes in the results table.",binding:{kind:"artifact-table",path:I,columnMeanings:{symbol:"identifier",log2FoldChange:"effect",padj:"p-value",rank_by_abs_log2fc:"count",of_genes:"count"},columnLabels:{symbol:"Gene",log2FoldChange:"log2 fold change",padj:"Adjusted p-value",rank_by_abs_log2fc:"Rank by |log2FC|",of_genes:"Genes ranked"}}}
]}}));
